        }
    }

    if ($needsRemap && $unlocked->isNotEmpty()) {
        return $this->remapFutureScheduledSessionsToContract($unlocked, $slots, $durationMinutes);
    }

    $sessionsByDate = [];
    foreach ($sessions as $session) {
        $date = $this->normalizeDateString($session->SessionDate ?? null);
        if ($date) {
